{
  "API_calls": [],
  "collected_information": {
    "environment": {
      "python_version": "3.9+ recommended, conda environment suggested",
      "installation": [
        "pip install --upgrade metagpt",
        "pip install --upgrade git+https://github.com/geekan/MetaGPT.git",
        "git clone https://github.com/geekan/MetaGPT && cd MetaGPT && pip install --upgrade -e ."
      ],
      "configuration": "metagpt --init-config to create ~/.metagpt/config2.yaml",
      "dependencies": "Pinned versions in requirements.txt including aiohttp==3.8.6, pandas==2.1.1, PyYAML==6.0.1, scikit_learn==1.3.2, rich==13.6.0 and others",
      "docker": {
        "base_image": "nikolaik/python-nodejs:python3.9-nodejs20-slim",
        "os_packages": ["git", "chromium", "fonts"],
        "env_variables": {
          "CHROME_BIN": "/usr/bin/chromium",
          "puppeteer_config": "/app/metagpt/config/puppeteer-config.json",
          "PUPPETEER_SKIP_CHROMIUM_DOWNLOAD": "true"
        },
        "node_packages": ["@mermaid-js/mermaid-cli globally installed"],
        "python_packages_installed": "requirements.txt and editable project install"
      }
    },
    "testing": {
      "framework": "pytest",
      "test_dependencies": "installed via pip install -e .[test]",
      "node_dependencies": ["@mermaid-js/mermaid-cli", "Playwright with dependencies"],
      "test_command": "export ALLOW_OPENAI_API_CALL=0; mkdir -p ~/.metagpt && cp tests/config2.yaml ~/.metagpt/config2.yaml; pytest --continue-on-collection-errors tests/ --ignore many tests including tests/metagpt/provider/test_bedrock_api.py --doctest-modules --cov=./metagpt/ --cov-report=xml:cov.xml --cov-report=html:htmlcov --durations=20",
      "coverage": "xml and html coverage reports generated, summary via coverage report -m",
      "note": "target test file tests/metagpt/provider/test_bedrock_api.py is ignored in batch run; to run individually use pytest tests/metagpt/provider/test_bedrock_api.py with same env setup",
      "no_requirements_test_txt": "test dependencies exclusively in setup extras"
    }
  },
  "terminate": true
}
